  str_aircraft_desc_7102005 = "Lumina Grid adalah pembangkit tenaga Colossus, <color=#00F6FF>memberikan lumina untuk setiap room</color>. Ini juga tempat favorit Firefly, sehingga kamu bisa meningkatkan <color=#00F6FF>kecepatan pemulihan Firefly</color> di ​​sini. Beberapa Aurorian tertentu sangat menyukai Firefly dan dapat mempercepat <color=#00F6FF>tingkat pemulihan Firefly</color>.",
  str_aircraft_desc_7103001 = "<color=#00F6FF>MS pada Luminameter</color> sangatlah penting saat menjelajahi Secret Territory. Matahari Buatan di sini mengisi ulang Luminameter, <color=#00F6FF>menyediakan dan memulihkan MS</color>. Beberapa Aurorian tertentu sangat suka bereksplorasi, dan dapat mempercepat <color=#00F6FF>tingkat pemulihan MS</color>.",
