  str_aircraft_desc_7103004 = "<color=#00F6FF>MS pada Luminameter</color> sangatlah penting saat menjelajahi Secret Territory. Matahari Buatan di sini mengisi ulang Luminameter, <color=#00F6FF>menyediakan dan memulihkan MS</color>. Beberapa Aurorian tertentu sangat suka bereksplorasi, dan dapat mempercepat <color=#00F6FF>tingkat pemulihan MS</color>.",
  str_aircraft_desc_7103005 = "<color=#00F6FF>MS pada Luminameter</color> sangatlah penting saat menjelajahi Wilayah Rahasia. Matahari Buatan di sini mengisi ulang Luminameter, <color=#00F6FF>menyediakan dan memulihkan MS</color>. Beberapa Aurorian tertentu sangat suka bereksplorasi, dan dapat mempercepat <color=#00F6FF>tingkat pemulihan MS</color>.",
  str_aircraft_desc_7104001 = "Kamu bisa <color=#00F6FF>pembuatan Carrier</color> di sini pada interval waktu tertentu, yang mengurangi jumlah Prism yang diperlukan untuk menyelesaikan panggung dan memberikan hasil Anda segera saat menggunakan Sweep. Aurorian tertentu bahkan memiliki Luminatics yang bisa <color=#00F6FF>meningkatkan kecepatan manufaktur Carrier</color>.",
